import * as THREE from 'three'
import React, { useRef, useEffect } from 'react'
import { useThree, useFrame } from 'react-three-fiber'
import lerp from 'lerp'
import { EffectComposer } from 'three/examples/jsm/postprocessing/EffectComposer'
import { RenderPass } from 'three/examples/jsm/postprocessing/RenderPass'
import { ShaderPass } from 'three/examples/jsm/postprocessing/ShaderPass'
import { UnrealBloomPass } from 'three/examples/jsm/postprocessing/UnrealBloomPass'
import { FXAAShader } from 'three/examples/jsm/shaders/FXAAShader'
import { EXPORT_WIDTH, EXPORT_HEIGHT } from './exportCapture'

export default function Effects({ visualRef, captureRef }) {
  const composer = useRef()
  const bloomPass = useRef()
  const fxaaPass = useRef()
  const settleFrames = useRef(0)
  const { scene, gl, size, camera } = useThree()

  useEffect(() => {
    if (!scene || !camera) return undefined
    gl.setClearColor(0x000000, 0)

    const w = Math.max(1, Math.floor(size.width))
    const h = Math.max(1, Math.floor(size.height))
    const comp = new EffectComposer(gl)
    comp.setPixelRatio(gl.getPixelRatio())
    comp.setSize(w, h)

    const renderPass = new RenderPass(scene, camera)
    const bloom = new UnrealBloomPass(new THREE.Vector2(w, h), 0.12, 0.85, 0.82)
    const fxaa = new ShaderPass(FXAAShader)
    const pr = gl.getPixelRatio()
    fxaa.uniforms.resolution.value.set(1 / (w * pr), 1 / (h * pr))

    comp.addPass(renderPass)
    comp.addPass(bloom)
    comp.addPass(fxaa)

    composer.current = comp
    bloomPass.current = bloom
    fxaaPass.current = fxaa

    return () => {
      if (comp.renderTarget1) comp.renderTarget1.dispose()
      if (comp.renderTarget2) comp.renderTarget2.dispose()
    }
  }, [gl, scene, camera, size.width, size.height])

  useFrame(() => {
    if (!composer.current || !visualRef?.current) return

    const v = visualRef.current
    const poolScale = v.poolScale ?? 0.62
    const bloomMix = Math.min(1, poolScale * v.lightIntensity / 1.8)

    if (bloomPass.current) {
      const targetStrength = Math.min(1.35, (v.bloom ?? 0.14) * poolScale * 0.95)
      const targetThreshold = lerp(v.bloomThreshold ?? 0.72, 0.42, bloomMix * 0.35)
      const bloomLerp = 0.11
      bloomPass.current.strength = lerp(bloomPass.current.strength, targetStrength, bloomLerp)
      bloomPass.current.threshold = lerp(bloomPass.current.threshold, targetThreshold, bloomLerp)
      bloomPass.current.radius = lerp(bloomPass.current.radius, 0.38 + poolScale * 0.22, bloomLerp)
    }

    const req = captureRef?.current
    if (req?.pending && !req._busy) {
      req._busy = true
      settleFrames.current = 0
      try {
        runFourKCapture({
          gl,
          camera,
          composer: composer.current,
          bloomPass: bloomPass.current,
          fxaaPass: fxaaPass.current,
          liveWidth: size.width,
          liveHeight: size.height,
          onDone: canvas => {
            req.pending = false
            req._busy = false
            if (typeof req.onComplete === 'function') req.onComplete(canvas)
          },
          onError: err => {
            req.pending = false
            req._busy = false
            if (typeof req.onError === 'function') req.onError(err)
          }
        })
      } catch (err) {
        req.pending = false
        req._busy = false
        if (typeof req.onError === 'function') req.onError(err)
      }
      return
    }

    composer.current.render()
  }, 1)

  return null
}

function runFourKCapture({
  gl,
  camera,
  composer,
  bloomPass,
  fxaaPass,
  liveWidth,
  liveHeight,
  onDone,
  onError
}) {
  const prevPr = gl.getPixelRatio()
  const prevSize = new THREE.Vector2()
  gl.getSize(prevSize)
  const prevAspect = camera.aspect

  const w = EXPORT_WIDTH
  const h = EXPORT_HEIGHT

  try {
    // Resize drawing buffer only — keep CSS size so layout doesn't jump
    gl.setPixelRatio(1)
    gl.setSize(w, h, false)
    camera.aspect = w / h
    camera.updateProjectionMatrix()

    composer.setPixelRatio(1)
    composer.setSize(w, h)
    if (bloomPass) bloomPass.setSize(w, h)
    if (fxaaPass?.uniforms?.resolution) {
      fxaaPass.uniforms.resolution.value.set(1 / w, 1 / h)
    }

    // Extra renders so bloom settles at the new resolution
    composer.render()
    composer.render()

    const out = document.createElement('canvas')
    out.width = w
    out.height = h
    const ctx = out.getContext('2d')
    // Fill opaque background first in case of any transparent pixels
    ctx.fillStyle = '#0f0f0f'
    ctx.fillRect(0, 0, w, h)
    ctx.drawImage(gl.domElement, 0, 0, w, h)

    restore()
    onDone(out)
  } catch (err) {
    try {
      restore()
    } catch (_) {
      /* */
    }
    onError(err)
  }

  function restore() {
    gl.setPixelRatio(prevPr)
    gl.setSize(liveWidth, liveHeight, false)
    // Prefer live DOM client size if available
    const el = gl.domElement
    if (el && el.clientWidth && el.clientHeight) {
      gl.setSize(el.clientWidth, el.clientHeight, false)
    } else if (prevSize.x && prevSize.y) {
      gl.setSize(prevSize.x, prevSize.y, false)
    }
    camera.aspect = prevAspect || liveWidth / Math.max(1, liveHeight)
    camera.updateProjectionMatrix()
    const rw = Math.max(1, Math.floor(el?.clientWidth || liveWidth || prevSize.x || 1))
    const rh = Math.max(1, Math.floor(el?.clientHeight || liveHeight || prevSize.y || 1))
    composer.setPixelRatio(gl.getPixelRatio())
    composer.setSize(rw, rh)
    if (bloomPass) bloomPass.setSize(rw, rh)
    if (fxaaPass?.uniforms?.resolution) {
      const pr = gl.getPixelRatio()
      fxaaPass.uniforms.resolution.value.set(1 / (rw * pr), 1 / (rh * pr))
    }
  }
}
