import React, { useCallback, useEffect, useRef, useState } from 'react'
import {
  canvasToJpegBlob,
  canvasToJpegDataUrl,
  cropToCanvas,
  downloadBlob,
  jpegBlobToPdfBlob,
  jpegDataUrlToSvgBlob,
  stampFilename
} from './exportCapture'

/**
 * Preview + crop + download for a captured landscape frame (no UI widgets).
 * Note: SVG export embeds the JPEG raster — true vector isn't available for this shader scene.
 */
export default function ExportModal({ open, sourceCanvas, capturing, error, onClose, onRetry }) {
  const stageRef = useRef(null)
  const [crop, setCrop] = useState(null)
  const [drag, setDrag] = useState(null)
  const [busy, setBusy] = useState(false)
  const [format, setFormat] = useState('jpeg')
  const [previewUrl, setPreviewUrl] = useState(null)

  const srcW = sourceCanvas?.width || 0
  const srcH = sourceCanvas?.height || 0

  useEffect(() => {
    if (!open || !sourceCanvas) {
      setPreviewUrl(null)
      setCrop(null)
      return undefined
    }
    setCrop({ x: 0, y: 0, width: sourceCanvas.width, height: sourceCanvas.height })
    let cancelled = false
    canvasToJpegDataUrl(sourceCanvas, 0.85).then(url => {
      if (!cancelled) setPreviewUrl(url)
    })
    return () => {
      cancelled = true
    }
  }, [open, sourceCanvas])

  const clampCrop = useCallback(
    next => {
      const minSize = Math.max(64, Math.round(Math.min(srcW, srcH) * 0.08))
      let x = Math.max(0, Math.min(srcW - minSize, next.x))
      let y = Math.max(0, Math.min(srcH - minSize, next.y))
      let width = Math.max(minSize, Math.min(srcW - x, next.width))
      let height = Math.max(minSize, Math.min(srcH - y, next.height))
      return { x, y, width, height }
    },
    [srcW, srcH]
  )

  const clientToImage = useCallback(
    (clientX, clientY) => {
      const stage = stageRef.current
      if (!stage || !srcW) return { x: 0, y: 0 }
      const rect = stage.getBoundingClientRect()
      const scaleX = srcW / rect.width
      const scaleY = srcH / rect.height
      return {
        x: (clientX - rect.left) * scaleX,
        y: (clientY - rect.top) * scaleY
      }
    },
    [srcW, srcH]
  )

  const onPointerDown = e => {
    if (!crop || capturing) return
    e.preventDefault()
    e.currentTarget.setPointerCapture(e.pointerId)
    const p = clientToImage(e.clientX, e.clientY)
    const handle = hitHandle(crop, p, srcW)
    if (handle === 'draw') {
      const origin = { x: p.x, y: p.y, width: 1, height: 1 }
      setCrop(clampCrop(origin))
      setDrag({ handle: 'draw', start: p, origin: { ...origin } })
      return
    }
    setDrag({
      handle,
      start: p,
      origin: { ...crop }
    })
  }

  const onPointerMove = e => {
    if (!drag) return
    const p = clientToImage(e.clientX, e.clientY)
    const dx = p.x - drag.start.x
    const dy = p.y - drag.start.y
    const o = drag.origin
    let next = { ...o }

    if (drag.handle === 'draw') {
      const x1 = Math.min(o.x, p.x)
      const y1 = Math.min(o.y, p.y)
      const x2 = Math.max(o.x, p.x)
      const y2 = Math.max(o.y, p.y)
      next = { x: x1, y: y1, width: x2 - x1, height: y2 - y1 }
    } else if (drag.handle === 'move') {
      next = { x: o.x + dx, y: o.y + dy, width: o.width, height: o.height }
      // keep size, clamp origin
      next.x = Math.max(0, Math.min(srcW - next.width, next.x))
      next.y = Math.max(0, Math.min(srcH - next.height, next.y))
    } else if (drag.handle === 'nw') {
      next = {
        x: o.x + dx,
        y: o.y + dy,
        width: o.width - dx,
        height: o.height - dy
      }
    } else if (drag.handle === 'ne') {
      next = {
        x: o.x,
        y: o.y + dy,
        width: o.width + dx,
        height: o.height - dy
      }
    } else if (drag.handle === 'sw') {
      next = {
        x: o.x + dx,
        y: o.y,
        width: o.width - dx,
        height: o.height + dy
      }
    } else if (drag.handle === 'se') {
      next = {
        x: o.x,
        y: o.y,
        width: o.width + dx,
        height: o.height + dy
      }
    }

    // Normalize inverted drags
    if (next.width < 0) {
      next.x += next.width
      next.width = Math.abs(next.width)
    }
    if (next.height < 0) {
      next.y += next.height
      next.height = Math.abs(next.height)
    }
    setCrop(clampCrop(next))
  }

  const onPointerUp = e => {
    if (!drag) return
    try {
      e.currentTarget.releasePointerCapture(e.pointerId)
    } catch (_) {
      /* */
    }
    setDrag(null)
  }

  const resetCrop = () => {
    if (!srcW) return
    setCrop({ x: 0, y: 0, width: srcW, height: srcH })
  }

  const download = async () => {
    if (!sourceCanvas || !crop || busy) return
    setBusy(true)
    try {
      const cropped = cropToCanvas(sourceCanvas, crop)
      const jpegBlob = await canvasToJpegBlob(cropped, 0.95)
      if (format === 'jpeg') {
        downloadBlob(jpegBlob, stampFilename('jpg'))
      } else if (format === 'pdf') {
        const pdf = await jpegBlobToPdfBlob(jpegBlob, cropped.width, cropped.height)
        downloadBlob(pdf, stampFilename('pdf'))
      } else {
        const dataUrl = await blobToDataUrlLocal(jpegBlob)
        const svg = jpegDataUrlToSvgBlob(dataUrl, cropped.width, cropped.height)
        downloadBlob(svg, stampFilename('svg'))
      }
    } catch (err) {
      console.error(err)
      alert(err.message || 'Export failed')
    } finally {
      setBusy(false)
    }
  }

  if (!open) return null

  const cropStyle =
    crop && srcW
      ? {
          left: `${(crop.x / srcW) * 100}%`,
          top: `${(crop.y / srcH) * 100}%`,
          width: `${(crop.width / srcW) * 100}%`,
          height: `${(crop.height / srcH) * 100}%`
        }
      : null

  return (
    <div className="voice-demo__export-overlay" role="dialog" aria-modal="true" aria-label="Export preview">
      <div className="voice-demo__export-modal">
        <div className="voice-demo__export-head">
          <div>
            <h2 className="voice-demo__export-title">Export view</h2>
            <p className="voice-demo__export-sub">
              {capturing
                ? 'Rendering 4K landscape…'
                : sourceCanvas
                  ? `${srcW}×${srcH} · mascot, canvas & lighting only`
                  : 'Waiting for frame…'}
            </p>
          </div>
          <button type="button" className="voice-demo__export-close" onClick={onClose} aria-label="Close">
            ×
          </button>
        </div>

        <div className="voice-demo__export-stage-wrap">
          {error ? (
            <div className="voice-demo__export-empty">
              <p>{error}</p>
              <button type="button" className="voice-demo__config-btn" onClick={onRetry}>
                Retry capture
              </button>
            </div>
          ) : capturing || !previewUrl ? (
            <div className="voice-demo__export-empty">Capturing 4K frame…</div>
          ) : (
            <div
              ref={stageRef}
              className="voice-demo__export-stage"
              onPointerDown={onPointerDown}
              onPointerMove={onPointerMove}
              onPointerUp={onPointerUp}
              onPointerCancel={onPointerUp}>
              <img className="voice-demo__export-image" src={previewUrl} alt="Export preview" draggable={false} />
              {cropStyle ? (
                <div className="voice-demo__export-crop" style={cropStyle}>
                  <span className="voice-demo__export-handle is-nw" data-handle="nw" />
                  <span className="voice-demo__export-handle is-ne" data-handle="ne" />
                  <span className="voice-demo__export-handle is-sw" data-handle="sw" />
                  <span className="voice-demo__export-handle is-se" data-handle="se" />
                </div>
              ) : null}
            </div>
          )}
        </div>

        <div className="voice-demo__export-toolbar">
          <div className="voice-demo__filter-row voice-demo__export-formats">
            {[
              { id: 'jpeg', label: 'JPEG' },
              { id: 'pdf', label: 'PDF' },
              { id: 'svg', label: 'SVG' }
            ].map(opt => (
              <button
                key={opt.id}
                type="button"
                className={`voice-demo__filter-chip${format === opt.id ? ' is-active' : ''}`}
                onClick={() => setFormat(opt.id)}
                disabled={capturing || !sourceCanvas}>
                {opt.label}
              </button>
            ))}
          </div>
          <p className="voice-demo__export-hint">
            Drag the frame to crop. SVG wraps the JPEG raster — true vector isn’t available for this 3D shader scene.
          </p>
          <div className="voice-demo__export-actions">
            <button type="button" className="voice-demo__config-btn" onClick={resetCrop} disabled={!sourceCanvas || capturing}>
              Reset crop
            </button>
            <button type="button" className="voice-demo__config-btn" onClick={onRetry} disabled={capturing}>
              Recapture
            </button>
            <button
              type="button"
              className="voice-demo__config-btn voice-demo__config-btn--primary"
              onClick={download}
              disabled={!sourceCanvas || capturing || busy}>
              {busy ? 'Preparing…' : `Download ${format.toUpperCase()}`}
            </button>
          </div>
        </div>
      </div>
    </div>
  )
}

function hitHandle(crop, p, srcW) {
  const edge = Math.max(24, srcW * 0.02)
  const inCrop =
    p.x >= crop.x && p.x <= crop.x + crop.width && p.y >= crop.y && p.y <= crop.y + crop.height
  const near = (x, y) => Math.hypot(p.x - x, p.y - y) <= edge
  if (near(crop.x, crop.y)) return 'nw'
  if (near(crop.x + crop.width, crop.y)) return 'ne'
  if (near(crop.x, crop.y + crop.height)) return 'sw'
  if (near(crop.x + crop.width, crop.y + crop.height)) return 'se'
  if (inCrop) return 'move'
  return 'draw'
}

function blobToDataUrlLocal(blob) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader()
    reader.onload = () => resolve(reader.result)
    reader.onerror = () => reject(reader.error || new Error('read failed'))
    reader.readAsDataURL(blob)
  })
}
